 stop-opacity=".9"/><stop offset="1" stop-color="#ffc45b" stop-opacity="0"/></radialGradient></defs><rect width="900" height="360" fill="url(#g3)"/><circle cx="708" cy="67" r="108" fill="url(#g4)"/><circle cx="708" cy="67" r="24" fill="#ffdfa0"/><path d="M0 250 142 175l94 45 110-108 92 121 98-71 115 90 91-50 158 52v106H0Z" fill="#283b48"/><path d="M360 301V147l88-70 89 70v154Z" fill="#263441" stroke="#998269" stroke-width="5"/><path d="M342 150 448 59l107 91" fill="none" stroke="#bea070" stroke-width="9"/><path d="M422 301V202h53v99" fill="#152330"/><path d="M397 183h19m62 0h19" stroke="#efcb82" stroke-width="8"/><path d="M443 119h11v59h-11z" fill="#ffdc89"/><circle cx="448" cy="118" r="32" fill="url(#g4)"/><path d="M0 310q130-32 240 3t243-2q126-30 417 5v44H0Z" fill="#15232d"/></svg>`;}
+function gameView(){if(state.screen==='ending')return endingView();const scene=scenes[state.step],role=roles.find(r=>r.id===state.role);return `<section class="intro"><div><div class="eyebrow">A choice-driven fantasy tale</div><h1>The Last Lantern</h1><p>Your choices shape the light that returns to Bellwether.</p></div><div class="step-pill">✧ &nbsp;CHAPTER ${state.step} OF 3</div></section><section class="game-layout"><article class="panel game-main"><div class="game-art">${sceneArt(scene.art)}<span class="art-caption">${scene.chapter}</span></div><div class="narrative"><div class="chapter-line">${scene.chapter}</div><h2>${scene.title}</h2><p>${scene.text}</p><p class="quote">${scene.quote}</p>${state.lastResult?`<p class="quote" style="font-style:normal!important;color:#597b65!important;border-color:#79a17b">${state.lastResult}</p>`:''}<div class="choices-label">What will you do?</div><div class="choice-list">${scene.choices.map((c,i)=>`<button class="choice-btn" data-choice="${i}"><span class="choice-icon">${c.icon}</span><span class="choice-text"><b>${c.title}</b><small>${c.sub}</small></span></button>`).join('')}</div></div></article><aside class="sidebar"><section class="panel side-panel"><div class="adventurer-head"><div class="avatar">${role.icon}</div><div><h3>${role.name}</h3><p>${role.trait} · Level 1 wayfarer</p></div></div><div class="divider"></div><div class="stat-label"><span>VITALITY</span><span>${state.health} / ${state.maxHealth}</span></div><div class="health-track"><div class="health-fill ${state.health<=2?'low':''}" style="width:${state.health/state.maxHealth*100}%"></div></div><div class="health-note">You can always finish the tale.</div><div class="divider"></div><div class="stat-grid"><div class="stat-chip"><span>Kindness</span><b>✦ ${state.hope}</b></div><div class="stat-chip"><span>Renown</span><b>♛ ${state.renown}</b></div></div><div class="divider"></div><div class="inventory-title">In your satchel</div><div class="inventory">${state.items.length?state.items.map(i=>`<span class="item-chip">${i}</span>`).join(''):'<span class="item-chip">Just a lantern</span>'}</div></section><section class="panel side-panel"><div class="inventory-title">The journey</div><div class="progress-list">${['The call','The crossing','The beacon'].map((x,i)=>`<div class="progress-item ${state.step===i+1?'active':state.step>i+1?'done':''}"><span class="progress-num">${state.step>i+1?'✓':i+1}</span>${x}</div>`).join('')}</div></section><section class="panel side-panel"><div class="side-quote">“Even a small light can show the way home.”<small>— Wayfarer’s saying</small></div></section></aside></section>`;}
+function endingData(){const acts=state.history.map(h=>h.kind);let score=state.hope+(state.role==='arcanist'?1:0)+(acts.includes('rescue')?1:0)+(acts.includes('kind')?1:0);if(state.role==='trickster'&&acts.includes('clever'))score++;if(score>=4)return {icon:'☀',title:'The Dawnbringer',stamp:'A bright new beginning',text:'The beacon flares like a second sunrise. The long night breaks, and warm gold spills over every rooftop in Bellwether. Keeper Elowen says your name will be told whenever the lanterns are lit. You didn’t just save the valley—you reminded it how to hope.'};if(score>=2)return {icon:'✦',title:'The Keeper’s Promise',stamp:'A light worth keeping',text:'A steady star shines above Bellwether once more. It is not the blazing sun of old, but a kinder, gentler light—and the valley gathers beneath it, safe for another generation. The keeper leaves you a place beside the beacon, should you ever wish to return.'};if(score>=0)return {icon:'♧',title:'A Lantern in the Dark',stamp:'The valley endures',text:'The beacon catches, sputters, then holds. Its light is small, but it is enough to guide the people of Bellwether through the night. You leave at dawn with tired feet, a full heart, and the knowledge that small acts can carry a long way.'};return {icon:'☾',title:'The Long Road Home',stamp:'Not every light is lost',text:'The beacon’s glow remains faint, and the valley must learn to make its own light for a while. But you brought Keeper Elowen home, and she will not let hope go dark. Your road is not over; somewhere beyond the hills, another story is already beginning.'};}
+function endingView(){const data=endingData(),role=roles.find(r=>r.id===state.role),recap=state.history.map(h=>h.title);return `<section class="intro"><div><div class="eyebrow">Your story has found its ending</div><h1>The Last Lantern</h1><p>Every choice left its mark. Here’s the tale you made together.</p></div><div class="step-pill">✧ &nbsp;THE END</div></section><section class="panel ending"><div class="ending-badge">${data.icon}</div><div class="chapter-line">Your ending</div><h2>${data.title}</h2><span class="ending-stamp">${data.stamp}</span><p style="margin-top:18px">${data.text}</p><p style="margin-top:13px;font-size:11px;color:#92928c">As ${role.name}, you chose to ${recap.join(', then ')}. Your kindness: ${state.hope} · Renown: ${state.renown} · Keepsakes found: ${state.items.length}.</p><div class="choice-list"><div class="stat-chip"><span>Wayfarer</span><b>${role.icon} ${role.name}</b></div><div class="stat-chip"><span>Story keepsakes</span><b>${state.items.length?state.items.join(' · '):'Just a lantern'}</b></div></div><button class="primary-btn" id="againBtn">Begin another tale &nbsp;↻</button></section>`;}
+function bind(){document.querySelectorAll('[data-role]').forEach(b=>b.addEventListener('click',()=>{state.role=b.dataset.role;render()}));const roll=$('#rollBtn');if(roll)roll.addEventListener('click',()=>{roll.classList.remove('rolling');void roll.offsetWidth;roll.classList.add('rolling');const index=Math.floor(Math.random()*roles.length);state.role=roles[index].id;render();showToast(`The dice chose ${roles[index].name}!`)});const start=$('#startBtn');if(start)start.addEventListener('click',begin);document.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>choose(Number(b.dataset.choice))));const again=$('#againBtn');if(again)again.addEventListener('click',reset);}
+function begin(){if(!state.role)return;const role=roles.find(r=>r.id===state.role);state.screen='game';state.maxHealth=role.health;state.health=role.health;state.step=1;state.hope=0;state.renown=0;state.items=[];state.history=[];state.lastResult='';render();window.scrollTo({top:0,behavior:'smooth'});}
+function choose(index){const scene=scenes[state.step],choice=scene.choices[index];if(!choice)return;let effect={...choice.effect};const role=state.role;if(scene.art==='fen'&&role==='ranger'&&effect.health<0){effect.health=0;effect.item='Marsh-glass';}if(choice.kind==='brave'&&role==='warden')effect.health=0;if(choice.kind==='clever'&&role==='trickster')effect.renown=(effect.renown||0)+1;if(choice.kind==='name'&&role==='arcanist')effect.hope=(effect.hope||0)+1;state.health=Math.max(1,Math.min(state.maxHealth,state.health+(effect.health||0)));state.hope+=effect.hope||0;state.renown+=effect.renown||0;if(effect.item&&!state.items.includes(effect.item))state.items.push(effect.item);state.history.push({kind:choice.kind,title:choice.title});state.lastResult=choice.result;if(choice.to===4){state.finalChoice=choice.kind;state.screen='ending';}else state.step=choice.to;render();window.scrollTo({top:0,behavior:'smooth'});}
+function reset(){state={screen:'setup',role:null,health:4,maxHealth:4,hope:0,renown:0,items:[],step:1,history:[],lastResult:'',finalChoice:null};render();window.scrollTo({top:0,behavior:'smooth'});}
+function showToast(message){const toast=$('#toast');toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2100);}
+function openHelp(){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop" id="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="helpTitle"><h2 id="helpTitle">A few words before you go</h2><p><strong>The Last Lantern</strong> is a tiny roleplaying adventure. Pick one of four wayfarers, or roll the die and let fate choose.</p><ul><li>Read each scene and choose the action that feels right.</li><li>Your choices change your keepsakes, vitality, and the ending.</li><li>Some heroes have a special edge in certain moments.</li><li>There are no wrong answers—and you can play again to find another ending.</li></ul><button class="primary-btn modal-close" id="closeHelp">Back to the story</button></section></div>`;$('#closeHelp').addEventListener('click',()=>root.innerHTML='');$('#backdrop').addEventListener('click',e=>{if(e.target.id==='backdrop')root.innerHTML=''});$('#closeHelp').focus();}
+$('#helpBtn').addEventListener('click',openHelp);$('#resetBtn').addEventListener('click',()=>{if(state.screen==='setup')return;reset();showToast('A fresh page, a new adventure.');});render();
+</script>
+</body>
+</html>

